import{_ as n,C as i,o as d,c as l,a2 as r,j as t,E as s,a as o}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"Remote Storage & Backup","description":"Local disk is the default: KomaYomi reads images from raw/, writes annotations to data/, and writes generated files to exports/. On top of that, the…","frontmatter":{"description":"Local disk is the default: KomaYomi reads images from raw/, writes annotations to data/, and writes generated files to exports/. On top of that, the…"},"headers":[],"relativePath":"remote-backup.md","filePath":"remote-backup.md","lastUpdated":1794762029000}'),c={name:"remote-backup.md"};function p(h,e,g,m,u,f){const a=i("Badge");return d(),l("div",null,[e[6]||(e[6]=r('<h1 id="remote-storage-backup" tabindex="-1">Remote Storage &amp; Backup <a class="header-anchor" href="#remote-storage-backup" aria-label="Permalink to &quot;Remote Storage &amp; Backup&quot;">​</a></h1><h2 id="what-exists-today" tabindex="-1">What exists today <a class="header-anchor" href="#what-exists-today" aria-label="Permalink to &quot;What exists today&quot;">​</a></h2><p>Local disk is the default: KomaYomi reads images from <code>raw/</code>, writes annotations to <code>data/</code>, and writes generated files to <code>exports/</code>. On top of that, the server supports <strong>remote image sources</strong> and <strong>remote backup destinations</strong> over WebDAV or a mounted/SMB network share, configured under <strong>Data tools → Storage</strong> and stored in <code>data/storage.json</code> (<code>schemaVersion: 1</code>).</p><p>Two portable local safety nets are also implemented.</p><h3 id="remote-image-source-webdav-network-drive" tabindex="-1">Remote image source (WebDAV / network drive) <a class="header-anchor" href="#remote-image-source-webdav-network-drive" aria-label="Permalink to &quot;Remote image source (WebDAV / network drive)&quot;">​</a></h3><p>A storage target of kind <code>webdav</code> or <code>network</code> can be set as <code>rawSource</code>.</p><ul><li><strong>Structure sync</strong> — <strong>Sync</strong> walks the remote tree and mirrors its folders into <code>raw/</code> as zero-byte placeholder files (up to 20,000 image files). The existing library scanner and naming rules keep working; the placeholders mark which pages exist.</li><li><strong>On-demand fetch</strong> — image bytes are downloaded the first time a page or thumbnail is opened, not during sync. Fetched files are cached under <code>data/cache/remote/files/</code>, addressed by a SHA-1 of the provider id plus the relative path.</li><li><strong>LRU cache</strong> — the cache is capped by <code>cacheLimitMb</code> (default <strong>512 MB</strong>). After each write the server prunes least-recently-used files until usage is below <strong>90%</strong> of the cap. The cache can be cleared from the storage UI.</li><li><strong>While offline</strong> — pages already in the cache stay readable. An uncached image returns HTTP <strong>503</strong> with code <code>ERR_REMOTE_UNAVAILABLE</code>; a failed thumbnail fetch returns <strong>502</strong> <code>ERR_THUMB_FETCH_FAILED</code>. The library keeps listing the pages instead of hanging or silently dropping them.</li><li><strong>Credentials</strong> — the user name is stored in <code>storage.json</code>; the password is encrypted with <strong>AES-256-GCM</strong> in <code>data/secrets.json.enc</code>, using a per-install key at <code>data/.secret.key</code> (mode <code>0600</code>). The API only reports <code>hasSecret</code>, never the password. This is a portable fallback, not an OS keychain; anyone who copies the whole data folder together with <code>.secret.key</code> can decrypt it.</li><li><strong>WebDAV details</strong> — Basic authentication, <code>PROPFIND</code> for listing/status, <code>GET</code> for reads, <code>PUT</code> for writes, 10-second request timeout. Read-only targets still work as a source but refuse uploads (<code>ERR_STORAGE_READONLY</code>).</li></ul><h3 id="backup-zip" tabindex="-1">Backup ZIP <a class="header-anchor" href="#backup-zip" aria-label="Permalink to &quot;Backup ZIP&quot;">​</a></h3><ul><li>Creates a ZIP of <code>data/</code> with every entry prefixed by <code>data/</code> and a <code>data/.backup-meta.json</code> marker.</li><li>Excludes the thumbnail cache and <code>.tmp</code> / <code>.log</code> files.</li><li>The file is written to <code>exports/</code> and offered as a download. If a backup target is selected, the same ZIP is uploaded to <code>backups/backup-&lt;timestamp&gt;.zip</code> on that target.</li><li><strong>Inspect before restore</strong> shows file count, page count, note count, volumes, templates, presets, how many files would be overwritten and the archive size.</li><li><strong>Restore</strong> writes same-named files under <code>data/</code>, but does not delete pages that are absent from the backup. A snapshot of the current data is written to <code>exports/</code> before anything is overwritten, so a mis-click is reversible.</li></ul><h3 id="mnproj-project-package" tabindex="-1"><code>.mnproj</code> project package <a class="header-anchor" href="#mnproj-project-package" aria-label="Permalink to &quot;`.mnproj` project package&quot;">​</a></h3><p>A ZIP with <code>manifest.json</code>, page JSON, templates and presets, in one of two modes:</p><ul><li><strong>Reference</strong> — records image paths and SHA-1 hashes. Small. If images moved, import can <strong>relink</strong> them from a chosen folder by hash first, then by filename.</li><li><strong>Packaged</strong> — embeds deduplicated images under <code>assets/&lt;sha1&gt;.&lt;ext&gt;</code>. Self-contained and portable, but large.</li></ul><p>Import behavior:</p><ul><li>A snapshot of <code>data/</code> is written first.</li><li>The original package is kept under <code>data/backups/projects/</code>.</li><li>Conflicts can be resolved as <strong>overwrite</strong>, <strong>merge</strong> or <strong>skip</strong>.</li><li><strong>Merge</strong> preserves existing panels/annotations when the incoming page lacks them, unions notes by id, and never deletes existing notes.</li></ul><p>See <a href="/KomaYomi-docs/data-format">Data Formats</a> for the manifest fields and folder layout.</p><h2 id="recommended-practice" tabindex="-1">Recommended practice <a class="header-anchor" href="#recommended-practice" aria-label="Permalink to &quot;Recommended practice&quot;">​</a></h2><ol><li><strong>Keep <code>raw/</code> on a large local disk</strong> (or an attached drive). It is the bulk of the data and is gitignored.</li><li><strong>Back up <code>data/</code> regularly</strong> with the Backup ZIP. It is small — mostly JSON — and contains all your work.</li><li><strong>Use <code>.mnproj</code> reference mode</strong> to move annotations between machines that already have the same images.</li><li><strong>Use <code>.mnproj</code> packaged mode</strong> to hand a self-contained project to someone else.</li><li><strong>Keep a copy of <code>exports/</code></strong> if you want to preserve generated study documents; it is gitignored and can be regenerated.</li><li><strong>Use a remote source for large libraries</strong> on a NAS; the on-demand cache keeps browsing responsive while avoiding a full local copy.</li></ol><h2 id="why-not-just-sync-the-folders" tabindex="-1">Why not just sync the folders? <a class="header-anchor" href="#why-not-just-sync-the-folders" aria-label="Permalink to &quot;Why not just sync the folders?&quot;">​</a></h2><p>You can put <code>raw/</code>, <code>data/</code> and <code>exports/</code> on a network drive or in a synced folder. The app does not lock files, but writes are atomic (<code>.tmp</code> + rename), so a sync client is unlikely to observe a partially written JSON. Avoid editing the same page from two machines at once; last write wins.</p><h2 id="planned-still-missing" tabindex="-1">Planned: still missing <a class="header-anchor" href="#planned-still-missing" aria-label="Permalink to &quot;Planned: still missing&quot;">​</a></h2><p>The following are <strong>not implemented</strong> and are listed here so expectations are clear:</p>',21)),t("ul",null,[t("li",null,[s(a,{type:"warning",text:"Planned"}),e[0]||(e[0]=o()),e[1]||(e[1]=t("strong",null,"Scheduled backups",-1)),e[2]||(e[2]=o(" — automatic periodic snapshots, locally or to a configured target.",-1))]),t("li",null,[s(a,{type:"warning",text:"Planned"}),e[3]||(e[3]=o()),e[4]||(e[4]=t("strong",null,[o("Remote sync of "),t("code",null,"data/"),o(" with version history")],-1)),e[5]||(e[5]=o(" — the WebDAV target currently serves images and receives backup ZIPs; it does not version the annotation database itself.",-1))])]),e[7]||(e[7]=r('<p>Until then, treat the Backup ZIP, remote backup upload and <code>.mnproj</code> as the supported transfer mechanisms.</p><h2 id="restore-checklist" tabindex="-1">Restore checklist <a class="header-anchor" href="#restore-checklist" aria-label="Permalink to &quot;Restore checklist&quot;">​</a></h2><ol><li>Click <strong>Backup</strong> and confirm the ZIP appears in <code>exports/</code> (or on the chosen remote target).</li><li>To restore: choose <strong>Inspect</strong>, review the counts, then <strong>Restore</strong>.</li><li>After restoring, reload the library; pages with annotations get a badge in the sidebar.</li><li>If a project import reports missing images, point <strong>relink directory</strong> at the folder that contains them and import again with <strong>merge</strong>.</li></ol>',3))])}const w=n(c,[["render",p]]);export{k as __pageData,w as default};
